164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Pet pet = petMapper.toPet(petFieldsDto);
173	        owner.setId(ownerId);
174	        pet.setOwner(owner);
175	        pet.getType().setName(null);
176	        this.clinicService.savePet(pet);
177	        PetDto petDto = petMapper.toPetDto(pet);
178	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
179	            .buildAndExpand(pet.getId()).toUri());
180	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
181	    }
