41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "The telephone number is already used by another owner";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
58	
59	    /**
60	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
61	     * class.
62	     *
63	     * @param e     Object referring to the thrown exception.
64	     * @param status HTTP response status.
65	     * @param url URL request.
66	     */
67	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
68	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
69	        problemDetail.setType(URI.create(url.toString()));
70	        problemDetail.setTitle(e.getClass().getSimpleName());
71	        problemDetail.setDetail(detail);
72	        problemDetail.setProperty("timestamp", Instant.now());
73	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
74	        return problemDetail;
75	    }
76	
77	    /**
78	     * Builds a 409 Conflict response for a create request that collides with an existing owner. The
79	     * body is a {@link ProblemDetail} carrying {@code detail} and an {@code errors} array naming the
80	     * conflicting fields, matching the shape produced for the other owner-creation error responses.
81	     *
82	     * @param e Object referring to the thrown exception.
83	     * @param request {@link HttpServletRequest} object referring to the current request.
84	     * @param detail the human-readable detail message.
85	     * @param errors the names of the fields whose values conflicted.
86	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
87	     */
88	    private ResponseEntity<ProblemDetail> conflict(Exception e, HttpServletRequest request, String detail, List<String> errors) {
89	        HttpStatus status = HttpStatus.CONFLICT;
90	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
91	        problemDetail.setProperty("errors", errors);
92	        return ResponseEntity.status(status).body(problemDetail);
93	    }
94	
95	    /**
96	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
97	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
98	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
99	     * would catch it and report an authorization failure as a 500.
100	     *
101	     * @param e The {@link AccessDeniedException} to propagate
102	     * @throws AccessDeniedException always
103	     */
104	    @ExceptionHandler(AccessDeniedException.class)
105	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
106	        throw e;
107	    }
108	
109	    /**
110	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
111	     *
112	     * @param e The {@link Exception} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
115	     */
116	    @ExceptionHandler(Exception.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
119	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
120	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
127	     * method returns a 404 Not Found status if an entity does not exist.
128	     *
129	     * @param e The {@link DataIntegrityViolationException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
132	     */
133	    @ExceptionHandler(DataIntegrityViolationException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
136	        logger.warn("Data integrity violation at {} {}: {}",
137	            request.getMethod(),
138	            request.getRequestURI(),
139	            e.getMessage());
140	        logger.debug("Data integrity violation stacktrace", e);
141	        HttpStatus status = HttpStatus.NOT_FOUND;
142	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
143	        return ResponseEntity.status(status).body(detail);
144	    }
145	
146	    /**
147	     * Handles exception thrown by Bean Validation on controller methods parameters
148	     *
149	     * @param e The {@link MethodArgumentNotValidException} to be handled
150	     * @param request {@link HttpServletRequest} object referring to the current request.
151	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
152	     */
153	    @ExceptionHandler(MethodArgumentNotValidException.class)
154	    @ResponseBody
155	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
156	        HttpStatus status = HttpStatus.BAD_REQUEST;
157	        BindingErrorsResponse errors = new BindingErrorsResponse();
158	        BindingResult bindingResult = e.getBindingResult();
159	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
160	        if (bindingResult.hasErrors()) {
161	            errors.addAllErrors(bindingResult);
162	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
163	                .map(FieldError::getField)
164	                .distinct()
165	                .toList();
166	            detail.setProperty("errors", invalidFields);
167	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
168	                .map(fieldError -> {
169	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
170	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
171	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
172	                        fieldError.getField(),
173	                        defaultMessage,
174	                        rejectedValue);
175	                    return new ValidationMessageDto(message)
176	                        .putAdditionalProperty("field", fieldError.getField())
177	                        .putAdditionalProperty("rejectedValue", rejectedValue)
178	                        .putAdditionalProperty("defaultMessage", defaultMessage);
179	                })
180	                .toList();
181	            logger.debug("Validation error at {} {}: {}",
182	                request.getMethod(),
183	                request.getRequestURI(),
184	                bindingResult.getFieldErrors());
185	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
186	            return ResponseEntity.status(status).body(detail);
187	        }
188	        return ResponseEntity.status(status).body(detail);
189	    }
190	
191	    /**
192	     * Handles {@link InvalidOwnerFieldsException} raised when an owner has required fields that are
193	     * present but blank (whitespace-only). Returns a 400 Bad Request whose body carries an
194	     * {@code errors} array listing the name of each blank field, mirroring the shape produced for
195	     * Bean Validation failures.
196	     *
197	     * @param e The {@link InvalidOwnerFieldsException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
200	     */
201	    @ExceptionHandler(InvalidOwnerFieldsException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
204	        HttpStatus status = HttpStatus.BAD_REQUEST;
205	        logger.debug("Blank owner fields at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getFields());
209	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
210	        detail.setProperty("errors", e.getFields());
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner submitted to the create
216	     * endpoint has a normalized telephone that is already used by another existing owner. Returns a
217	     * 409 Conflict.
218	     *
219	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
222	     */
223	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
226	        logger.debug("Duplicate owner telephone at {} {}: {}",
227	            request.getMethod(),
228	            request.getRequestURI(),
229	            e.getTelephone());
230	        return this.conflict(e, request, ERROR_DUPLICATE_TELEPHONE, List.of("telephone"));
231	    }
232	
233	    /**
234	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner submitted to the create
235	     * endpoint shares a household with an existing owner (same last name and address) without opting
236	     * in via {@code sharesHousehold}. Returns a 409 Conflict.
237	     *
238	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
239	     * @param request {@link HttpServletRequest} object referring to the current request.
240	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
241	     */
242	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
243	    @ResponseBody
244	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
245	        logger.debug("Duplicate owner household at {} {}: {}, {}",
246	            request.getMethod(),
247	            request.getRequestURI(),
248	            e.getLastName(),
249	            e.getAddress());
250	        return this.conflict(e, request, ERROR_DUPLICATE_HOUSEHOLD, List.of("lastName", "address"));
251	    }
252	
253	}
